import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../App.css";

const RateUser = () => {
  const [usersToRate, setUsersToRate] = useState([]);
  const userId = sessionStorage.getItem("userId");

  useEffect(() => {
    if (userId) {
      fetch(`${API_BASE_URL}/api/ratings/partners/${userId}`)
        .then((res) => res.json())
        .then((data) => {
          console.log("Users fetched to rate:", data);
          setUsersToRate(Array.isArray(data) ? data : []);
        })
        .catch((err) => {
          console.error("Failed to load users to rate:", err);
          setUsersToRate([]);
        });
    }
  }, [userId]);

  const handleRate = async (ratedUserId, rating) => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/ratings`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          rater_id: userId,
          rated_id: ratedUserId,
          rating,
        }),
      });

      if (res.ok) {
        alert("Rating submitted!");
        setUsersToRate((prev) => prev.filter((u) => u.id !== ratedUserId));
      } else {
        alert("Failed to submit rating.");
      }
    } catch (err) {
      console.error("Rating error:", err);
      alert("Error submitting rating.");
    }
  };

  return (
    <div className="dashboard-wrapper">
      <Navbar />
      <main className="dashboard-main" style={{ padding: "40px" }}>
        <h2 style={{ textAlign: "center", marginBottom: "24px" }}>Rate Other Users</h2>
        {usersToRate.length === 0 ? (
          <p style={{ textAlign: "center" }}>No users to rate yet.</p>
        ) : (
          <div className="item-grid">
            {usersToRate.map((user) => (
              <div className="item-card" key={user.id}>
                <h4>{user.username}</h4>
                <p><strong>Email:</strong> {user.email}</p>
                <div style={{ marginTop: "10px" }}>
                  {[1, 2, 3, 4, 5].map((star) => (
                    <button
                      key={star}
                      onClick={() => handleRate(user.id, star)}
                      style={{
                        marginRight: "6px",
                        backgroundColor: "#2563eb",
                        color: "white",
                        border: "none",
                        borderRadius: "5px",
                        padding: "6px 10px",
                        cursor: "pointer",
                      }}
                    >
                      {star}⭐
                    </button>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}
      </main>
      <Footer />
    </div>
  );
};

export default RateUser;
